    int monotoneIncreasingDigits(int n) {
        string s = to_string(n);
        int marker = s.size();
        for (int i = (int)s.size() - 1; i > 0; i--) {
            if (s[i - 1] > s[i]) {
                s[i - 1]--;
                marker = i;
            }
        }
        for (int i = marker; i < (int)s.size(); i++) {
            s[i] = '9';
        }
        return stoi(s);
    }
